from __future__ import annotations

from typing import Any

VERDICT_PASSED = "TESTS_PASSED"
VERDICT_INCONCLUSIVE = "INCONCLUSIVE"

LIMITATIONS = [
    "The patch is a deterministic demo patch, not generated by an AI model.",
    "Only the bundled fixture is executed; arbitrary repositories are not accepted.",
    "Passing this test suite is evidence, not a proof of universal correctness.",
]

REPORT_KEYS = frozenset(
    {
        "status",
        "scenario",
        "repository",
        "mode",
        "summary",
        "verdict",
        "baseline",
        "verification",
        "patch",
        "limitations",
    }
)


def decide_verdict(baseline: dict[str, Any], verification: dict[str, Any]) -> str:
    """A fix is verified only when the baseline failed and the post-patch run passed."""
    if baseline.get("passed") is False and verification.get("passed") is True:
        return VERDICT_PASSED
    return VERDICT_INCONCLUSIVE


REAL_LIMITATIONS = [
    "Only the executed test suite was run; passing it is evidence, not a proof of universal correctness.",
    "The diagnosis and patch were proposed by an AI model and verified by independent test execution.",
    "Untested behavior, unrun test files, and skipped tests are outside this verdict.",
]

REAL_REPORT_KEYS = frozenset(
    {
        "status",
        "repository",
        "commit_sha",
        "mode",
        "summary",
        "verdict",
        "diagnosis",
        "diagnosis_confidence",
        "baseline",
        "verification",
        "patch",
        "guard",
        "execution",
        "attempts",
        "outcome",
        "limitations",
    }
)


def build_report(
    *,
    scenario: str,
    repository: str,
    mode: str,
    baseline: dict[str, Any],
    verification: dict[str, Any],
    patch: dict[str, str],
) -> dict[str, Any]:
    """Build the investigation report. Keys match the existing API contract."""
    verdict = decide_verdict(baseline, verification)
    verified = verdict == VERDICT_PASSED
    return {
        "status": "complete",
        "scenario": scenario,
        "repository": repository,
        "mode": mode,
        "summary": (
            "The baseline reproduced a failure, and the demo patch passed the bundled tests."
            if verified
            else "The expected baseline-to-passing-test sequence did not occur. Inspect the test output."
        ),
        "verdict": verdict,
        "baseline": baseline,
        "verification": verification,
        "patch": patch,
        "limitations": list(LIMITATIONS),
    }


def build_real_report(
    *,
    repository: str,
    commit_sha: str,
    mode: str,
    diagnosis: str,
    baseline: dict[str, Any],
    verification: dict[str, Any],
    patch: dict[str, Any],
    guard: dict[str, Any],
    execution: dict[str, Any],
    attempts: int,
    extra_limitations: list[str] | None = None,
) -> dict[str, Any]:
    """Build a real-repository investigation report.

    Keys match REAL_REPORT_KEYS. A fix is verified only on a genuine
    baseline-failed to verification-passed transition; anything else is
    an unconfirmed hypothesis. ``outcome`` names the evidence class
    explicitly: ``verified_fix``, ``already_green``, ``not_executed``,
    or ``reproduced_unfixed``.
    """
    verdict = decide_verdict(baseline, verification)
    verified = verdict == VERDICT_PASSED
    if verified:
        outcome = "verified_fix"
    elif (baseline or {}).get("passed") is True:
        outcome = "already_green"
    elif (baseline or {}).get("passed") is None:
        outcome = "not_executed"
    else:
        outcome = "reproduced_unfixed"
    failing = len((baseline or {}).get("failures", []))
    return {
        "status": "complete",
        "repository": repository,
        "commit_sha": commit_sha,
        "mode": mode,
        "summary": (
            f"Reproduced {failing} failing test(s); the guarded patch passed "
            "the independent verification run."
            if verified
            else "The failure-to-passing-test transition did not occur. "
            "Inspect the baseline and verification output."
        ),
        "verdict": verdict,
        "diagnosis": diagnosis,
        "diagnosis_confidence": "confirmed" if verified else "hypothesis",
        "baseline": baseline,
        "verification": verification,
        "patch": patch,
        "guard": guard,
        "execution": execution,
        "attempts": attempts,
        "outcome": outcome,
        "limitations": list(REAL_LIMITATIONS) + list(extra_limitations or []),
    }
